#!/usr/bin/env bash
# filename: api-customer.sh
# Code Generated by Sidekick is for learning and experimentation purposes only.

# ============================================================================
# DEPENDENCIES CHECK
# ============================================================================
if ! command -v jq &>/dev/null; then
    echo "ERROR: jq is required. Install with: sudo apt-get install -y jq"
    exit 1
fi

# ============================================================================
# CONFIGURATION
# ============================================================================
API_GATEWAY="http://localhost:8080"
AUTH_SERVICE="http://localhost:9000"
FRAUD_SERVICE="http://localhost:8004"
PUBLISHABLE_KEY="pk_test_123"

pass=0
fail=0
SESSION_ID=""
MC_TOKEN=""
PAYMENT_ID=""
JWT=""
abort=false
declare -a result_tests=()
declare -a result_statuses=()

RESP_FILE="/tmp/api_customer_resp.json"

# ── Colors ────────────────────────────────────────────────────────────────────
CY="\e[36m"
GR="\e[32m"
RD="\e[31m"
YL="\e[33m"
WH="\e[37m"
RS="\e[0m"

# ============================================================================
# HELPER FUNCTIONS
# ============================================================================
write_header() {
    echo ""
    echo -e "${CY}$(printf '=%.0s' {1..70})${RS}"
    echo -e "${CY}  $1${RS}"
    echo -e "${CY}$(printf '=%.0s' {1..70})${RS}"
}

pass_test() {
    echo -e "  ${GR}[PASS]${RS} $1"
    ((pass++))
    result_tests+=("$1")
    result_statuses+=("PASS")
}

fail_test() {
    echo -e "  ${RD}[FAIL]${RS} $1"
    [[ -n "$2" ]] && echo -e "         ${RD}$2${RS}"
    ((fail++))
    result_tests+=("$1")
    result_statuses+=("FAIL: $2")
}

# Returns 0 if HTTP 2xx, 1 otherwise. Sets $HTTP_CODE and $BODY globals.
do_get() {
    local url="$1"; shift
    HTTP_CODE=$(curl -s -o "$RESP_FILE" -w "%{http_code}" --max-time 10 "$@" "$url" 2>/dev/null)
    BODY=$(cat "$RESP_FILE" 2>/dev/null)
    [[ "$HTTP_CODE" -ge 200 && "$HTTP_CODE" -lt 300 ]]
}

do_post() {
    local url="$1"; local data="$2"; shift 2
    HTTP_CODE=$(curl -s -o "$RESP_FILE" -w "%{http_code}" --max-time 30 \
        -X POST -H "Content-Type: application/json" \
        -d "$data" "$@" "$url" 2>/dev/null)
    BODY=$(cat "$RESP_FILE" 2>/dev/null)
    [[ "$HTTP_CODE" -ge 200 && "$HTTP_CODE" -lt 300 ]]
}

ts() { date +%Y%m%d%H%M%S; }

# ── Banner ────────────────────────────────────────────────────────────────────
echo ""
echo -e "  ${CY}CUSTOMER FLOW - COMPLETE TEST SUITE${RS}"
echo -e "${CY}$(printf '=%.0s' {1..70})${RS}"

# ============================================================================
# TEST 1: HEALTH CHECKS
# ============================================================================
write_header "TEST 1: HEALTH CHECKS"

echo -e "\n  ${YL}Checking API Gateway...${RS}"
if do_get "$API_GATEWAY/health"; then
    STATUS=$(echo "$BODY" | jq -r '.status // empty')
    if [[ "$STATUS" == "ok" || "$STATUS" == "up" ]]; then
        pass_test "API Gateway healthy"
    else
        fail_test "API Gateway unhealthy" "status=$STATUS"
        abort=true
    fi
else
    fail_test "API Gateway unreachable" "HTTP $HTTP_CODE"
    abort=true
fi

echo -e "\n  ${YL}Checking Auth Service...${RS}"
if do_get "$AUTH_SERVICE/health"; then
    STATUS=$(echo "$BODY" | jq -r '.status // empty')
    if [[ "$STATUS" == "ok" || "$STATUS" == "up" ]]; then
        pass_test "Auth Service healthy"
    else
        fail_test "Auth Service unhealthy" "status=$STATUS"
        abort=true
    fi
else
    fail_test "Auth Service unreachable" "HTTP $HTTP_CODE"
    abort=true
fi

echo -e "\n  ${YL}Checking Fraud Service...${RS}"
if do_get "$FRAUD_SERVICE/health"; then
    STATUS=$(echo "$BODY" | jq -r '.status // empty')
    if [[ "$STATUS" == "ok" || "$STATUS" == "up" ]]; then
        pass_test "Fraud Service healthy"
    else
        fail_test "Fraud Service unhealthy" "status=$STATUS"
    fi
else
    fail_test "Fraud Service unreachable" "HTTP $HTTP_CODE"
fi

if $abort; then
    echo -e "\n  ${RD}[ABORTED] Gateway or Auth unreachable. Fix connectivity and re-run.${RS}\n"
    exit 0
fi

# ============================================================================
# TEST 2: AUTHENTICATION
# ============================================================================
write_header "TEST 2: AUTHENTICATION"

echo -e "\n  ${YL}Requesting JWT...${RS}"
JWT_BODY=$(jq -n \
    --arg sub "cust_$(ts)" \
    --arg email "customer@gmail.com" \
    '{
        sub: $sub,
        email: $email,
        roles: ["customer"],
        scopes: [
            "payment_session:create",
            "payment_session:read_own",
            "payment_method:tokenize",
            "payment_intent:confirm_own",
            "public_config:read"
        ]
    }')

if do_post "$AUTH_SERVICE/token" "$JWT_BODY"; then
    JWT=$(echo "$BODY" | jq -r '.access_token // empty')
    if [[ -n "$JWT" ]]; then
        pass_test "JWT token obtained"
        echo -e "    ${WH}Token  : ${JWT:0:50}...${RS}"
    else
        fail_test "JWT token empty or missing"
        abort=true
    fi
else
    fail_test "JWT request failed" "HTTP $HTTP_CODE"
    abort=true
fi

if $abort; then
    echo -e "\n  ${RD}[ABORTED] Cannot continue without JWT.${RS}\n"
    exit 0
fi

# ── Shared customer headers (passed to curl as args) ─────────────────────────
CUST_HEADERS=(
    -H "Authorization: Bearer $JWT"
    -H "X-Publishable-Key: $PUBLISHABLE_KEY"
)

# ============================================================================
# TEST 3: PUBLIC CONFIGURATION
# ============================================================================
write_header "TEST 3: PUBLIC CONFIGURATION"

echo -e "\n  ${YL}Fetching config...${RS}"
if do_get "$API_GATEWAY/v1/customer/config" "${CUST_HEADERS[@]}"; then
    MERCHANT_ID=$(echo "$BODY" | jq -r '.merchant_id // empty')
    METHODS=$(echo "$BODY" | jq -r '.supported_methods // [] | join(", ")')
    if [[ -n "$MERCHANT_ID" ]]; then
        pass_test "Config retrieved"
        echo -e "    ${WH}Merchant ID : $MERCHANT_ID${RS}"
        echo -e "    ${WH}Methods     : $METHODS${RS}"
    else
        fail_test "Config missing merchant_id"
    fi
else
    fail_test "Config request failed" "HTTP $HTTP_CODE"
fi

# ============================================================================
# TEST 4: PAYMENT SESSION
# ============================================================================
write_header "TEST 4: PAYMENT SESSION"

echo -e "\n  ${YL}Creating session (capture=true)...${RS}"
SESSION_BODY=$(jq -n \
    --arg cart "cart_$(ts)" \
    --arg order "order_$(ts)" \
    '{
        cart_id: $cart,
        order_id: $order,
        amount: 7500,
        currency: "usd",
        description: "Customer test order",
        metadata: { test: "customer_flow", env: "bash" },
        capture: true
    }')

if do_post "$API_GATEWAY/v1/customer/payment_sessions" "$SESSION_BODY" "${CUST_HEADERS[@]}"; then
    SESSION_ID=$(echo "$BODY" | jq -r '.session_id // empty')
    AMOUNT=$(echo "$BODY" | jq -r '.amount // 0')
    CURRENCY=$(echo "$BODY" | jq -r '.currency // ""' | tr '[:lower:]' '[:upper:]')
    STATUS=$(echo "$BODY" | jq -r '.status // ""')
    EXPIRES=$(echo "$BODY" | jq -r '.expires_at // ""')
    if [[ -n "$SESSION_ID" ]]; then
        pass_test "Session created"
        echo -e "    ${WH}Session ID : $SESSION_ID${RS}"
        echo -e "    ${WH}Amount     : \$$(echo "scale=2; $AMOUNT/100" | bc) $CURRENCY${RS}"
        echo -e "    ${WH}Status     : $STATUS${RS}"
        echo -e "    ${WH}Expires    : $EXPIRES${RS}"
    else
        fail_test "Session ID missing from response"
        abort=true
    fi
else
    fail_test "Session creation failed" "HTTP $HTTP_CODE"
    abort=true
fi

echo -e "\n  ${YL}Retrieving session...${RS}"
if [[ -n "$SESSION_ID" ]]; then
    if do_get "$API_GATEWAY/v1/customer/payment_sessions/$SESSION_ID" "${CUST_HEADERS[@]}"; then
        STATUS=$(echo "$BODY" | jq -r '.status // ""')
        if [[ "$STATUS" == "created" ]]; then
            pass_test "Session retrieved - status: $STATUS"
        else
            fail_test "Unexpected status: $STATUS"
        fi
    else
        fail_test "Session retrieval failed" "HTTP $HTTP_CODE"
    fi
else
    fail_test "Session retrieval skipped - no session ID"
fi

echo -e "\n  ${YL}Creating auth-only session (capture=false)...${RS}"
AUTH_SESS_BODY=$(jq -n \
    --arg cart "cart_auth_$(ts)" \
    '{cart_id: $cart, amount: 5000, currency: "usd", capture: false}')

if do_post "$API_GATEWAY/v1/customer/payment_sessions" "$AUTH_SESS_BODY" "${CUST_HEADERS[@]}"; then
    SID=$(echo "$BODY" | jq -r '.session_id // empty')
    CAPTURE=$(echo "$BODY" | jq -r '.capture // ""')
    if [[ -n "$SID" ]]; then
        pass_test "Auth-only session created - capture: $CAPTURE"
    else
        fail_test "Auth-only session missing ID"
    fi
else
    fail_test "Auth-only session failed" "HTTP $HTTP_CODE"
fi

# ============================================================================
# TEST 5: CARD TOKENIZATION
# ============================================================================
write_header "TEST 5: CARD TOKENIZATION"

echo -e "\n  ${YL}Tokenizing Visa...${RS}"
if do_post "$API_GATEWAY/v1/customer/payment_methods/tokenize" \
    '{"card_number":"4242424242424242","exp_month":12,"exp_year":2026,"cvc":"123"}' \
    "${CUST_HEADERS[@]}"; then
    TOKEN=$(echo "$BODY" | jq -r '.payment_method_token // empty')
    BRAND=$(echo "$BODY" | jq -r '.brand // ""')
    LAST4=$(echo "$BODY" | jq -r '.last4 // ""')
    if [[ -n "$TOKEN" ]]; then
        pass_test "Visa tokenized - brand:$BRAND last4:$LAST4"
    else
        fail_test "Visa token missing"
    fi
else
    fail_test "Visa tokenization failed" "HTTP $HTTP_CODE"
fi

echo -e "\n  ${YL}Tokenizing Mastercard...${RS}"
if do_post "$API_GATEWAY/v1/customer/payment_methods/tokenize" \
    '{"card_number":"5555555555554444","exp_month":12,"exp_year":2026,"cvc":"123"}' \
    "${CUST_HEADERS[@]}"; then
    TOKEN=$(echo "$BODY" | jq -r '.payment_method_token // empty')
    BRAND=$(echo "$BODY" | jq -r '.brand // ""')
    LAST4=$(echo "$BODY" | jq -r '.last4 // ""')
    if [[ -n "$TOKEN" ]]; then
        pass_test "Mastercard tokenized - brand:$BRAND last4:$LAST4"
        MC_TOKEN="$TOKEN"
    else
        fail_test "Mastercard token missing"
    fi
else
    fail_test "Mastercard tokenization failed" "HTTP $HTTP_CODE"
fi

echo -e "\n  ${YL}Tokenizing Amex...${RS}"
if do_post "$API_GATEWAY/v1/customer/payment_methods/tokenize" \
    '{"card_number":"378282246310005","exp_month":12,"exp_year":2026,"cvc":"1234"}' \
    "${CUST_HEADERS[@]}"; then
    TOKEN=$(echo "$BODY" | jq -r '.payment_method_token // empty')
    BRAND=$(echo "$BODY" | jq -r '.brand // ""')
    LAST4=$(echo "$BODY" | jq -r '.last4 // ""')
    if [[ -n "$TOKEN" ]]; then
        pass_test "Amex tokenized - brand:$BRAND last4:$LAST4"
    else
        fail_test "Amex token missing"
    fi
else
    fail_test "Amex tokenization failed" "HTTP $HTTP_CODE"
fi

# ============================================================================
# TEST 6: PAYMENT CONFIRMATION
# ============================================================================
write_header "TEST 6: PAYMENT CONFIRMATION"

echo -e "\n  ${YL}Confirming payment (Mastercard)...${RS}"
if [[ -n "$SESSION_ID" && -n "$MC_TOKEN" ]]; then
    CONFIRM_BODY=$(jq -n \
        --arg sid "$SESSION_ID" \
        --arg tok "$MC_TOKEN" \
        '{session_id: $sid, payment_method_token: $tok}')
    if do_post "$API_GATEWAY/v1/customer/payment_intents/confirm" \
        "$CONFIRM_BODY" "${CUST_HEADERS[@]}"; then
        PAYMENT_ID=$(echo "$BODY" | jq -r '.session.payment_id // empty')
        PAY_STATUS=$(echo "$BODY" | jq -r '.session.status // ""')
        ORDER_ID=$(echo "$BODY" | jq -r '.session.order_id // ""')
        AMOUNT=$(echo "$BODY" | jq -r '.session.amount // 0')
        if [[ -n "$PAYMENT_ID" ]]; then
            pass_test "Payment confirmed"
            echo -e "    ${WH}Payment ID     : $PAYMENT_ID${RS}"
            echo -e "    ${WH}Payment Status : $PAY_STATUS${RS}"
            echo -e "    ${WH}Order ID       : $ORDER_ID${RS}"
            echo -e "    ${WH}Amount         : \$$(echo "scale=2; $AMOUNT/100" | bc)${RS}"
        else
            fail_test "Payment confirmed but payment_id missing"
        fi
    else
        ERR=$(echo "$BODY" | jq -r '.detail // .message // ""' 2>/dev/null)
        fail_test "Payment confirmation failed" "$ERR (HTTP $HTTP_CODE)"
    fi
else
    [[ -z "$SESSION_ID" ]] && fail_test "Confirm skipped - no session ID available"
    [[ -z "$MC_TOKEN"   ]] && fail_test "Confirm skipped - no Mastercard token available"
fi

# ============================================================================
# TEST 7: ERROR HANDLING
# ============================================================================
write_header "TEST 7: ERROR HANDLING"

echo -e "\n  ${YL}Testing invalid publishable key...${RS}"
BAD_KEY_HEADERS=(
    -H "Authorization: Bearer $JWT"
    -H "X-Publishable-Key: pk_invalid_999"
)
if do_get "$API_GATEWAY/v1/customer/config" "${BAD_KEY_HEADERS[@]}"; then
    fail_test "Invalid key should have been rejected"
else
    pass_test "Invalid key rejected - HTTP $HTTP_CODE"
fi

echo -e "\n  ${YL}Testing missing publishable key...${RS}"
NO_KEY_HEADERS=(-H "Authorization: Bearer $JWT")
if do_get "$API_GATEWAY/v1/customer/config" "${NO_KEY_HEADERS[@]}"; then
    fail_test "Missing key should have been rejected"
else
    pass_test "Missing key rejected"
fi

echo -e "\n  ${YL}Testing invalid session ID...${RS}"
if [[ -n "$MC_TOKEN" ]]; then
    INV_SESS_BODY=$(jq -n \
        --arg tok "$MC_TOKEN" \
        '{session_id: "ps_invalid_000", payment_method_token: $tok}')
    if do_post "$API_GATEWAY/v1/customer/payment_intents/confirm" \
        "$INV_SESS_BODY" "${CUST_HEADERS[@]}"; then
        fail_test "Invalid session should have been rejected"
    else
        pass_test "Invalid session rejected"
    fi
fi

echo -e "\n  ${YL}Testing invalid payment method token...${RS}"
FRESH_BODY=$(jq -n \
    --arg cart "cart_err_$(ts)" \
    --arg order "order_err_$(ts)" \
    '{cart_id: $cart, order_id: $order, amount: 1000, currency: "usd", capture: true}')
if do_post "$API_GATEWAY/v1/customer/payment_sessions" \
    "$FRESH_BODY" "${CUST_HEADERS[@]}"; then
    FRESH_SID=$(echo "$BODY" | jq -r '.session_id // empty')
    if [[ -n "$FRESH_SID" ]]; then
        INV_TOK_BODY=$(jq -n \
            --arg sid "$FRESH_SID" \
            '{session_id: $sid, payment_method_token: "pm_invalid_token"}')
        if do_post "$API_GATEWAY/v1/customer/payment_intents/confirm" \
            "$INV_TOK_BODY" "${CUST_HEADERS[@]}"; then
            fail_test "Invalid token should have been rejected"
        else
            pass_test "Invalid token rejected"
        fi
    fi
fi

echo -e "\n  ${YL}Testing expired JWT...${RS}"
EXPIRED_JWT="eyJhbGciOiJSUzI1NiJ9.eyJzdWIiOiJ0ZXN0IiwiZXhwIjoxfQ.invalid"
EXPIRED_HEADERS=(
    -H "Authorization: Bearer $EXPIRED_JWT"
    -H "X-Publishable-Key: $PUBLISHABLE_KEY"
)
if do_get "$API_GATEWAY/v1/customer/config" "${EXPIRED_HEADERS[@]}"; then
    fail_test "Expired JWT should have been rejected"
else
    pass_test "Expired JWT rejected"
fi

# ============================================================================
# FINAL SUMMARY
# ============================================================================
TOTAL=$((pass + fail))
echo ""
echo -e "${CY}$(printf '=%.0s' {1..70})${RS}"
echo -e "${CY}  FINAL RESULTS${RS}"
echo -e "${CY}$(printf '=%.0s' {1..70})${RS}"
echo ""
echo -e "  ${WH}Total : $TOTAL${RS}"
echo -e "  ${GR}PASS  : $pass${RS}"
echo -e "  ${RD}FAIL  : $fail${RS}"

if [[ -n "$PAYMENT_ID" ]]; then
    echo ""
    echo -e "  ${CY}Payment ID : $PAYMENT_ID${RS}"
    echo -e "  ${CY}Session ID : $SESSION_ID${RS}"
fi

echo ""
if [[ $fail -eq 0 ]]; then
    echo -e "  ${GR}ALL TESTS PASSED${RS}"
else
    echo -e "  ${YL}SOME TESTS FAILED - review output above${RS}"
fi

echo ""
echo -e "${CY}Detailed Results:${RS}"
printf "%-55s %s\n" "Test" "Result"
printf "%-55s %s\n" "$(printf -- '-%.0s' {1..54})" "--------"
for i in "${!result_tests[@]}"; do
    if [[ "${result_statuses[$i]}" == "PASS" ]]; then
        COLOR=$GR
    else
        COLOR=$RD
    fi
    printf "${COLOR}%-55s %s${RS}\n" "${result_tests[$i]}" "${result_statuses[$i]}"
done
echo ""

rm -f "$RESP_FILE"

